export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "13:50。防災學習館附設研修資料室。技術紀錄區。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪從退役硬體閱覽區走過來。走廊盡頭是另一個房間。門上貼著一張標示——公共安全技術紀錄。館內查詢終端。微縮膠片閱讀機。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯剛才那本手冊。離線設定載體。掌心長。薄金屬殼。單側金色接點。暴力撬出時護片翹起。這些字——和第一輪車廂廣播裡的「尖銳物」——是同一類東西的兩個名字。我需要冷靜。不能讓這個發現把推論拉得太遠。先做下一件事。獨立來源。不能讓所有答案都從同一個交付包裡出來。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她走進技術紀錄區。房間比剛才的閱覽室小。兩排金屬鐵架。架上放著退役設備的紙本手冊、裝訂成冊的採購紀錄、舊防災技術研討會論文集。角落有一台微縮膠片閱讀機。靠牆是一台館內查詢終端。螢幕是舊型的。鍵盤泛黃。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她在查詢終端前坐下。螢幕亮起來。搜尋介面很簡單。欄位——關鍵字、年份、文件類型、主管單位。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯不能搜千田的名字。直接搜人名會讓這次調閱看起來像針對特定個人的背景調查。館員會記住。記錄會留。要從設備型號和程序類別入手。搜退役載體的改訂紀錄。搜採購驗收附件。搜防災技術研討會。讓查詢看起來像在追硬體型號的歷史，不是在追一個人。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她輸入關鍵字。TKS-SYNC。退役載體。離線復舊。版本回復。年份設定在事件前五年至前一年。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕顯示結果。十二條。她逐條看。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "前幾條是退役設備改訂通知。型號編號。改訂日期。主管單位。沒有人名。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第七條——舊防災技術研討會論文集。三年前。主題：公共安全系統離線復舊程序與載體管理。主辦單位——東京都防災協議會。協辦——東都危機システム株式会社。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯東都危機システム。TKS。研討會。離線復舊程序。這不是研修教材。是技術研討會的公開論文集。不同來源。不同管道。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她記下研討會名稱和年份。繼續往下看。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第十一條——採購驗收附件。型號與退役載體同系列。驗收項目——離線復舊載體程序驗證。驗收年度——事件前兩年。承包單位——東都危機システム株式会社。公共安全系統部。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯採購驗收附件。程序驗證。同系列設備。承包單位是 TKS 公共安全系統部。這也不是研修教材。是採購流程的正式附件。公共紀錄。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她站起來。走到鐵架前。找到採購驗收附件的裝訂冊。厚。封面是標準公共工程格式。她翻到目錄頁。找到第十一條對應的頁碼。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "裝訂冊很厚。她往第十一條的頁碼翻。中途翻過幾頁附錄。後段是一般的營運持續附錄。標準公共工程格式。每一頁都是制式的災害復舊排程。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "其中一頁是灣岸 continuity transport 的預置時段表。制式表格。欄位很單調——", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "BCP CUTOVER　23:50。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "PREPOSITION WINDOW　23:50–05:50。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "MAR-CONT　PROTECTIVE TRANSFER CLASS。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "表格下方的附註用普通文字寫——此為災害復舊時之灣岸 continuity transport 預置時段，涵蓋關鍵人員與設備之海上轉移，屬保護性轉移類別。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯營運持續附錄。災害復舊的灣岸 continuity transport。關鍵人員設備海上轉移。這些是公共工程驗收文件裡常見的災害復舊排程。不是我需要的。我需要的是簽署欄。翻過去。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她翻過那一頁。繼續往第十一條翻。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她翻到那一頁。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "驗收報告的格式很制式。型號。批次。驗收日期。驗收項目。簽署欄。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "驗收項目——離線復舊載體程序驗證／版本回復作業監修。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "簽署欄。監修者姓名。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "千田浩介。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著那三個字。看了幾秒。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯千田。在這裡。不是研修教材的範例。不是我自己查到的名字。是採購驗收附件上印著的簽署欄。公共紀錄。事件前兩年。他簽了這份驗收。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她往下看。簽署欄下方有單位資訊。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "千田浩介。東都危機システム株式会社。公共安全系統部。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "職務欄——離線復舊載體程序驗證／版本回復作業監修。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯寫下來。全部抄。不能漏。不能加。原件寫什麼就抄什麼。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她翻開筆記本。找到空白頁。一欄一欄抄。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "來源——採購驗收附件。公共工程格式。事件前兩年。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "驗收項目——離線復舊載體程序驗證／版本回復作業監修。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "監修者——千田浩介。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "單位——東都危機システム株式会社。公共安全系統部。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她抄完之後，翻到研討會論文集那一條。走回鐵架。找到那本裝訂冊。翻到目錄。找到離線復舊程序相關的頁碼。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她翻過去。論文集的格式和驗收附件不同。有摘要。有議程表。有講者名單。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "講者名單。第三位。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "千田浩介。東都危機システム株式会社。公共安全系統部。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "講題——離線復舊載體之版本驗證程序與現場操作規範。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯兩個來源。採購驗收附件。防災技術研討會論文集。都不是研修教材。都不是同一個交付包裡的東西。一個是公共工程驗收紀錄。一個是公開研討會。兩份獨立文件。同一個名字。同一個單位。同一個職務領域。離線復舊載體。程序驗證。版本回復。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把研討會的講者資訊也抄進筆記本。來源。講題。姓名。單位。年份。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "抄完之後，她放下筆。看著這兩條抄錄。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯這兩份文件能證明什麼。第一——千田知道此類載體如何操作。他是程序驗證的監修者。他簽署了驗收報告。他在公開研討會上講過版本驗證程序。這不是推測。是公共紀錄上的正式職務。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯第二——他知道原始載體與普通複製檔的差別。驗收項目寫的是「程序驗證」和「版本回復」。這涉及簽署鏈。涉及授權。涉及控制台是否承認載入的版本。普通複製檔缺少簽署與授權鏈——這是剛才手冊裡寫的。千田監修的就是這個程序的驗證。他不可能不知道差別。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯第三——他有合理職務機會接觸同系列設備。他在 TKS 公共安全系統部。他負責離線復舊載體的程序驗證。這是他的工作。不是額外的。不是偷偷的。是正式職務。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯第四——他可能理解如何保存不可遠端改寫的歷史版本。版本回復作業監修。這個職務名稱本身就涉及——把特定版本從系統中帶出來、保存下來、在需要時恢復。他知道怎麼做。他有權限做。至少在正常職務範圍內。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著這四條推論。看了很久。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯但這兩份文件不能證明什麼。不能證明他星期一拔走的是 TOKYO-7。驗收附件是事件前兩年的。研討會是三年前的。都早於星期一。都沒有提到 TOKYO-7。都沒有提到任何特定設定檔名稱。只提到程序。只提到型號系列。只提到職務。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯不能證明他知道孩子研究。採購驗收附件和研討會論文集都是公共安全系統的技術文件。裡面沒有受試者。沒有端點。沒有研究中心。沒有睡眠研究。只有載體。只有程序。只有版本。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯不能證明他是東京方案的核心設計者。他是程序驗證的監修者。不是設定檔的設計者。不是方案的策劃者。驗證和設計是不同的職務。監修和核心是不同的位置。他知道載體怎麼運作。不一定知道載體裡裝了什麼。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯不能證明第一輪那個物件仍然可讀。就算千田有能力取出載體。就算他第一輪真的交給了我什麼東西。那個東西經過暴力撬出。護片撕裂。金色接點外露。手冊上寫——必須以「疑似受損設定載體」隔離處理。受損的載體不一定還能讀。我不確定它還在不在。第二輪裡它已經不在了。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她翻到筆記本的新一頁。拿起筆。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她在頁面中間寫下兩行。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "千田有能力。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "不等於千田當晚做過。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯這是界線。能力不等於行為。他有職務上的知識和權限。這是事實。但事實只到這裡。星期一晚上他做了什麼——這兩份文件不回答。他為什麼出現在那輛車上——這兩份文件不回答。他交給我的那個東西到底裝了什麼——這兩份文件不回答。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她在兩行字下面再加一行。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "來源：採購驗收附件（事件前兩年）＋防災技術研討會論文集（事件前三年）。獨立於研修教材。獨立於退役載體手冊。不同管道。同一結論——千田具備操作此類載體的職務能力。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她放下筆。看了一眼時間。14:35。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她站起來。把裝訂冊放回鐵架。走到櫃台。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.ArchiveStaff, character: "資料室職員", dialogue: "技術紀錄區的資料，請在閉館前三十分鐘拍完。今天四點半閉館。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "好。我想確認一下——採購驗收附件和研討會論文集的館藏登錄資訊。我需要記下來。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.ArchiveStaff, character: "資料室職員", dialogue: "登錄資訊在裝訂冊封面內頁。可以抄錄。不能整頁影印。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "好。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她回到鐵架。翻開兩本裝訂冊的封面內頁。把館藏登錄編號、送存日期、主管單位全部抄進筆記本。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "然後她拿起手機。對著採購驗收附件的簽署欄那一頁拍了一張。包含完整頁面。頁碼。裝訂冊編號。不只是簽署欄。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "又翻到研討會論文集的講者名單那一頁。拍了一張。同樣包含完整頁面。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "拍完之後，她把兩本裝訂冊放回原位。回到查詢終端前。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯兩個來源。兩張照片。兩段抄錄。館藏登錄資訊。這些都是公共紀錄。都是合法調閱。不是非法登入。不是私下取得。是館內閱覽。是規則允許的範圍內。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她關掉終端螢幕。收好筆記本。拉上背包。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "14:55。她走出技術紀錄區。走廊的光已經偏黃。下午。高窗外的光線開始斜了。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯今天的資料室。三個區域。研修教材——TOKYO-7 的名字。退役硬體手冊——離線設定載體的形制。技術紀錄區——千田的名字。三個獨立的來源。三層。不能混。研修教材證明 TOKYO-7 是歷史別名。手冊證明離線載體的形制和用途。技術紀錄證明千田有能力操作此類載體。三層。三個獨立的結論。不能疊成一個。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她走到閱覽室門口。停了一秒。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯千田。你在第一輪把那個東西塞給我的時候——你知道它是什麼。你知道它不是尖銳物。你知道它不是刃物狀金屬片。你知道它是一個載體。你知道它裝了什麼。或者——你至少知道它應該裝什麼。但你沒有時間說。你只說了——不要救東京。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯不要救東京。東京是一個設定檔。東京有一個維護別名。TOKYO-7。千田有能力把歷史版本從系統裡帶出來。這三件事——都是今天確認的。但三件事之間的連線——還不能畫。不能畫等號。不能跨過去。", background: Background.Chapter_15_Ch15_Act4_S0, portrait: Portrait.AsakuraMio_Sad },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她推開門。走進走廊。腳步聲在空蕩的走廊裡很輕。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "背包裡有筆記本。筆記本裡有兩行字。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "千田有能力。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "不等於千田當晚做過。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "界線。清楚。不能跨。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "15:10。她走出資料室大門。外面的空氣比館內冷。下午的光已經開始變弱。距星期一 06:13——大約一天十五小時四十三分鐘。", background: Background.Chapter_15_Ch15_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "悠真失蹤第十二日。", background: Background.Chapter_15_Ch15_Act4_S0 },
];
